nodes.notes:
Triggered by Express POST /integrations/pipeline/analyze
Payload: { intakeId, filename, email, attachments, attachmentCount }
Webhook URL: https://ndt-v1.on-nex.us/n8n/webhook/ndt-pipeline

parameters.jsCode:
const raw = $input.first().json;
const body = (raw && raw.body !== undefined) ? raw.body : raw;
const intakeId = body.intakeId;
const email = body.email || {};
const attachments = body.attachments || [];

const emailText = [
  `From: ${email.from || ''}`,
  `Subject: ${email.subject || ''}`,
  `Date: ${email.date || ''}`,
  '',
  email.body || ''
].join('\n');

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId,
      stepKey: 'intake',
      status: 'success',
      log: `Intake \u00b7 ${attachments.length} attachment(s) \u00b7 from: ${email.from || 'unknown'} \u00b7 subject: ${email.subject || '(no subject)'}`,
      detail: { attachmentCount: attachments.length, from: email.from, subject: email.subject },
    },
  });
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: { intakeId, stepKey: 'email_sanitize', status: 'processing', log: 'Starting email sanitization' },
  });
} catch (_) {}

return [{ json: { intakeId, emailText, attachments, email } }];

// Branch A: Sanitize email body before LLM analysis.
// URL resolved from 00-PRE config; falls back to hardcoded URL.
const ctx = $input.first().json;
const preProcConfig = ctx.preProcConfig || {};
const stepCfg = preProcConfig['email_sanitization'];
const serviceUrl = (stepCfg?.is_active !== false && stepCfg?.webhook_url)
  ? stepCfg.webhook_url
  : 'http://sanitize:8011/sanitize';

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: serviceUrl,
  headers: { 'Content-Type': 'application/json' },
  body: {
    comply_doc_id: null,
    intake_id: ctx.intakeId,
    text: ctx.emailText,
    routing: 'CLOUD_OK',
  },
  timeout: 30000,
});

return [{ json: result }];

// Resolve gateway URL from 00-PRE config; fall back to hardcoded.
const _preProcCfg = $('B: Fetch Pre-Processing Config').first().json.preProcConfig || {};
const _emailLlmStep = _preProcCfg['email_llm_analysis'];
const GATEWAY_URL_RESOLVED = (_emailLlmStep?.is_active !== false && _emailLlmStep?.webhook_url)
  ? _emailLlmStep.webhook_url
  : GATEWAY_URL_RESOLVED;

const intakeId = $('Extract Intake Data').first().json.intakeId;
const sanitizeResult = $input.first().json;

// Update step: email sanitization done, LLM starting
try {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId,
      stepKey: 'email_sanitize',
      status: 'success',
      log: `Tokenized ${sanitizeResult.entity_count ?? 0} entities \u00b7 routing: CLOUD_OK \u00b7 job: ${(sanitizeResult.job_id||'').slice(0,8)}`,
      detail: { entityCount: sanitizeResult.entity_count ?? 0, jobId: sanitizeResult.job_id, routing: 'CLOUD_OK' },
      serviceName: 'sanitize',
      endpoint: 'http://sanitize:8011/sanitize',
      responsePayload: { entity_count: sanitizeResult.entity_count ?? 0, job_id: sanitizeResult.job_id },
    },
  });
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId,
      stepKey: 'email_llm',
      status: 'processing',
      log: 'Sending to LLM for quote param extraction',
      serviceName: 'gateway',
      endpoint: GATEWAY_URL_RESOLVED,
      requestPayload: { intake_id: intakeId, sanitize_job_id: sanitizeResult.job_id, classification: 'CLEAN', llm_routing: 'CLOUD_OK', prompt: (sanitizeResult.sanitized_text || '').slice(0, 3000), system_prompt: 'You are an NDT quote analyst. Extract structured quote parameters from this email. Return JSON with: customerName (string), inspectionType (one of: UT, RT, MT, PT, ET, VT), partNumber (string — the part or job number if mentioned, otherwise "N/A"), specification (string — the inspection specification or standard referenced e.g. ASTM E1742, MIL-STD-1916, AMS, otherwise "N/A"), notes (string), estimatedItems (array of objects with geometryType, quantity, description).' },
    },
  });
} catch (_) {}

// Try LLM analysis -- non-fatal, continue even if it fails
const t0 = Date.now();
let llmResponse = null;
try {
  llmResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: GATEWAY_URL_RESOLVED,
    headers: { 'Content-Type': 'application/json' },
    body: {
      intake_id: intakeId,
      sanitize_job_id: sanitizeResult.job_id,
      classification: 'CLEAN',
      llm_routing: 'CLOUD_OK',
      system_prompt: 'You are an NDT quote analyst. Extract structured quote parameters from this email. Return JSON with: customerName (string), inspectionType (one of: UT, RT, MT, PT, ET, VT), partNumber (string — the part or job number if mentioned, otherwise "N/A"), specification (string — the inspection specification or standard referenced e.g. ASTM E1742, MIL-STD-1916, AMS, otherwise "N/A"), notes (string), estimatedItems (array of objects with geometryType, quantity, description).',
      prompt: sanitizeResult.sanitized_text || '',
    },
  });
} catch (err) {
  llmResponse = { error: err.message, response_json: null, provider_used: 'none' };
}

// Update step: email LLM done (success or graceful failure)
const llmOk = llmResponse && !llmResponse.error;
const latencyMs = Date.now() - t0;
try {
  if (llmOk) {
    const rj = (typeof llmResponse.response_json === 'string'
      ? JSON.parse(llmResponse.response_json)
      : llmResponse.response_json) || {};
    await this.helpers.httpRequest({
      method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
      headers: { 'Content-Type': 'application/json' },
      body: {
        intakeId,
        stepKey: 'email_llm',
        status: 'success',
        log: `${llmResponse.provider_used}/${llmResponse.model_used} \u00b7 ${llmResponse.prompt_tokens ?? '?'} tokens \u00b7 customer: ${rj.customerName||'?'} \u00b7 type: ${rj.inspectionType||'?'} \u00b7 part: ${rj.partNumber||'N/A'} \u00b7 spec: ${rj.specification||'N/A'}`,
        detail: { provider: llmResponse.provider_used, model: llmResponse.model_used, tokens: llmResponse.prompt_tokens, customerName: rj.customerName, inspectionType: rj.inspectionType, partNumber: rj.partNumber||'N/A', specification: rj.specification||'N/A' },
        serviceName: 'gateway',
        endpoint: GATEWAY_URL_RESOLVED,
        httpStatus: 200,
        latencyMs,
        responsePayload: { provider: llmResponse.provider_used, model: llmResponse.model_used, tokens: llmResponse.prompt_tokens, response_json: typeof llmResponse.response_json === 'string' ? llmResponse.response_json.slice(0, 5000) : JSON.stringify(llmResponse.response_json || {}).slice(0, 5000) },
      },
    });
  } else {
    await this.helpers.httpRequest({
      method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
      headers: { 'Content-Type': 'application/json' },
      body: {
        intakeId,
        stepKey: 'email_llm',
        status: 'skipped',
        log: `Skipped \u00b7 ${llmResponse?.error || 'LLM unavailable'} \u00b7 email params not extracted`,
        serviceName: 'gateway',
        endpoint: GATEWAY_URL_RESOLVED,
        httpStatus: 500,
        latencyMs,
        responsePayload: { error: llmResponse?.error || 'LLM unavailable' },
      },
    });
  }
} catch (_) {}

return [{ json: { email_analysis: true, response_json: llmResponse?.response_json || null, provider_used: llmResponse?.provider_used || 'none', model_used: llmResponse?.model_used || null, prompt_tokens: llmResponse?.prompt_tokens || null } }];

const attachment = $input.first();
const prevItem = $('Branch B: Split Attachments').first().json;
const intakeId = $('Extract Intake Data').first().json.intakeId;

// Get binary data and base64 encode
const binaryKey = Object.keys(attachment.binary || {})[0];
// n8n v2: use getBinaryDataBuffer to get actual bytes (not a file ref)
let content_b64 = '';
if (binaryKey) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, binaryKey);
    content_b64 = buf.toString('base64');
  } catch (_) {
    const binaryData = attachment.binary?.[binaryKey];
    content_b64 = binaryData?.data || '';
  }
}

// Detect MIME type from extension
const ext = (prevItem.filename || '').split('.').pop().toLowerCase();
const MEDIA_TYPES = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', bmp: 'image/bmp', tiff: 'image/tiff', tif: 'image/tiff', pdf: 'application/pdf' };
const media_type = MEDIA_TYPES[ext] || 'application/octet-stream';

return [{
  json: {
    intakeId,
    filename: prevItem.filename,
    content_b64,
    media_type
  }
}];

// Branch B: ITAR/EAR classification with OCR text extraction.
// URL resolved from 00-PRE config; falls back to hardcoded URL.
const ctx = $input.first().json;
const preProcConfig = $('B: Fetch Pre-Processing Config').first().json.preProcConfig || {};
const stepCfg = preProcConfig['compliance_classification'];
const serviceUrl = (stepCfg?.is_active !== false && stepCfg?.webhook_url)
  ? stepCfg.webhook_url
  : 'http://comply:8010/classify';

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: serviceUrl,
  headers: { 'Content-Type': 'application/json' },
  body: {
    intake_id: ctx.intakeId,
    filename: ctx.filename,
    content_b64: ctx.content_b64,
  },
  timeout: 120000,
});

return [{ json: result }];

const _hiid = $input.first().json.intake_id || $('Extract Intake Data').first().json.intakeId;
try {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: { intakeId: _hiid, stepKey: 'comply_classify', status: 'success', log: 'Document classified as HOLD' },
  });
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: { intakeId: _hiid, stepKey: 'compliance_gate', status: 'failed', log: 'HOLD - document requires human review before LLM processing' },
  });
} catch (_) {}

// Document requires human review â€” pass through classify result with no LLM output
const classify = $input.first().json;
return [{
  json: {
    doc_id: classify.doc_id,
    filename: classify.filename,
    classification: classify.classification,
    llm_routing: classify.llm_routing,
    risk_score: classify.risk_score,
    typeCode: null,
    typeLabel: null,
    preprocessed_data: null,
    llm_output: null,
    skipped_reason: 'HOLD â€” human review required'
  }
}];

// Branch B: Tokenize drawing numbers, CAGE codes, entities before LLM.
// URL resolved from 00-PRE config; falls back to hardcoded URL.
const ctx = $input.first().json;
const preProcConfig = $('B: Fetch Pre-Processing Config').first().json.preProcConfig || {};
const stepCfg = preProcConfig['pii_sanitization'];
const serviceUrl = (stepCfg?.is_active !== false && stepCfg?.webhook_url)
  ? stepCfg.webhook_url
  : 'http://sanitize:8011/sanitize';

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: serviceUrl,
  headers: { 'Content-Type': 'application/json' },
  body: {
    comply_doc_id: ctx.doc_id,
    intake_id: ctx.intake_id,
    text: ctx.doc_id + ' ' + ctx.filename + ' drawing ' + (ctx.drawing_number || ''),
    routing: ctx.llm_routing,
  },
  timeout: 30000,
});

return [{ json: result }];

const _intakeId = $('Extract Intake Data').first().json.intakeId;
const _complyResult = $('Branch B: Comply Classify').first().json;

// Build rich comply_classify log
const _clsLog = `${_complyResult.classification} \u00b7 risk: ${_complyResult.risk_score ?? 0} \u00b7 routing: ${_complyResult.llm_routing} \u00b7 USML hits: ${(_complyResult.usml_hits||[]).length} \u00b7 drawing: ${_complyResult.drawing_number||'none'} \u00b7 CAGE: ${(_complyResult.cage_codes||[]).join(',')||'none'}`;

// Build compliance_gate reason
const _routing = _complyResult.llm_routing;
const _gateReason = _routing === 'CLOUD_OK' ? 'Cleared for cloud LLM'
  : _routing === 'LOCAL_ONLY' ? 'ITAR/EAR_HIGH \u2014 routed to local model'
  : 'Human review required';

try {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _intakeId,
      stepKey: 'comply_classify',
      status: 'success',
      log: _clsLog,
      detail: {
        classification: _complyResult.classification,
        riskScore: _complyResult.risk_score,
        routing: _complyResult.llm_routing,
        usmlHits: _complyResult.usml_hits?.length ?? 0,
        drawingNumber: _complyResult.drawing_number,
        cageCodes: _complyResult.cage_codes,
      },
      serviceName: 'comply',
      endpoint: 'http://comply:8010/classify',
      responsePayload: {
        classification: _complyResult.classification,
        risk_score: _complyResult.risk_score,
        llm_routing: _complyResult.llm_routing,
        drawing_number: _complyResult.drawing_number,
        cage_codes: _complyResult.cage_codes,
        usml_hits_count: (_complyResult.usml_hits||[]).length,
      },
    },
  });
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _intakeId,
      stepKey: 'compliance_gate',
      status: 'success',
      log: `${_complyResult.llm_routing} \u00b7 ${_gateReason}`,
    },
  });
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _intakeId,
      stepKey: 'sanitize_pii',
      status: 'processing',
      log: `Tokenizing entities in: ${_complyResult.filename || 'attachment'}`,
      serviceName: 'sanitize',
      endpoint: 'http://sanitize:8011/sanitize',
      requestPayload: { filename: _complyResult.filename },
    },
  });
} catch (_) {}

// Detect NDT inspection type from filename and email subject/body
const sanitizeResult = $input.first().json;
const complyResult = $('Branch B: Comply Classify').first().json;
const email = $('Extract Intake Data').first().json.email || {};

const filename = (complyResult.filename || '').toLowerCase();
const emailText = [
  email.subject || '',
  email.body || ''
].join(' ').toLowerCase();

// Order matters: check more specific patterns first
const patterns = [
  { code: 'RT', keywords: ['radiograph', ' rt ', '_rt_', '-rt-', 'xray', 'x-ray', 'x ray', 'film shot', 'iridium', 'gamma ray', 'rt inspection'] },
  { code: 'UT', keywords: ['ultrasonic', ' ut ', '_ut_', '-ut-', 'phased array', 'tofd', 'immersion scan', 'shear wave', 'ut inspection', 'flaw detect'] },
  { code: 'MT', keywords: ['magnetic particle', ' mt ', '_mt_', '-mt-', 'magnaflux', 'mt inspection'] },
  { code: 'PT', keywords: ['penetrant', ' pt ', '_pt_', '-pt-', 'dye penetrant', 'liquid penetrant', 'pt inspection'] },
  { code: 'ET', keywords: ['electromagnetic', ' et ', '_et_', '-et-', 'eddy current', 'et inspection'] },
  { code: 'VT', keywords: ['visual testing', ' vt ', '_vt_', '-vt-', 'visual insp'] },
];

let detectedCode = 'UT'; // default to UT (most common for NDT portal)
let matchedKeyword = 'default';

for (const { code, keywords } of patterns) {
  const hit = keywords.find(kw => filename.includes(kw) || emailText.includes(kw));
  if (hit) {
    detectedCode = code;
    matchedKeyword = hit.trim();
    break;
  }
}

return [{
  json: {
    typeCode: detectedCode,
    matchedKeyword,
    complyResult,
    sanitizedText: sanitizeResult.sanitized_text,
    sanitizeJobId: sanitizeResult.job_id,
  }
}];

// Match detected type code to DB record and carry forward context
const allTypes = $input.all().map(i => i.json); // all items from split httpRequest
const ctx = $('B: Detect Inspection Type Code').first().json;
const { typeCode, complyResult, sanitizedText, sanitizeJobId } = ctx;

// Find matching type; fall back to UT if not found
const matched =
  (Array.isArray(allTypes) ? allTypes : []).find(t => t.code === typeCode) ||
  (Array.isArray(allTypes) ? allTypes : []).find(t => t.code === 'UT') ||
  { id: null, code: typeCode, label: typeCode + ' Inspection' };

return [{
  json: {
    typeId: matched.id,
    typeCode: matched.code,
    typeLabel: matched.label,
    complyResult,
    sanitizedText,
    sanitizeJobId,
  }
}];

// Run all non-llm inspection steps in sort_order; collect preprocessed data.
// ALL llm steps are forwarded in allLlmSteps so the Gateway node loops them.
const rawSteps = $input.all().map(i => i.json); // steps array from httpRequest split
const ctx = $('B: Match Type + Resolve ID').first().json;

const steps = (Array.isArray(rawSteps) ? rawSteps : [])
  .filter(s => s.is_active)
  .sort((a, b) => a.sort_order - b.sort_order);

const preprocessorSteps = steps.filter(s => s.action_type !== 'llm');
const llmSteps = steps.filter(s => s.action_type === 'llm');
const llmStep = llmSteps[0];

const preprocessedData = {};

for (const step of preprocessorSteps) {
  if (step.action_type === 'webhook' && step.webhook_url) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'POST',
        url: step.webhook_url,
        headers: { 'Content-Type': 'application/json' },
        body: {
          stepName: step.name,
          typeCode: ctx.typeCode,
          classification: ctx.complyResult.classification,
          filename: ctx.complyResult.filename,
          drawingNumber: ctx.complyResult.drawing_number,
          sanitizedText: ctx.sanitizedText,
          sanitizeJobId: ctx.sanitizeJobId,
        },
      });
      preprocessedData[step.name] = response;
    } catch (err) {
      preprocessedData[step.name] = { skipped: true, error: err.message };
    }
  } else if (step.action_type === 'n8n' && step.n8n_workflow) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'POST',
        url: `http://n8n:5678/webhook/${step.n8n_workflow}`,
        headers: { 'Content-Type': 'application/json' },
        body: {
          stepName: step.name,
          typeCode: ctx.typeCode,
          filename: ctx.complyResult.filename,
          sanitizedText: ctx.sanitizedText,
        },
      });
      preprocessedData[step.name] = response;
    } catch (err) {
      preprocessedData[step.name] = { skipped: true, error: err.message };
    }
  } else {
    preprocessedData[step.name] = { skipped: true, reason: `action_type=${step.action_type} not yet wired` };
  }
}

const defaultInstruction = 'You are an NDT technical analyst. Extract structured parameters from the document. Return JSON with: partNumber, material, wallThickness, diameter, weldType, ndeSpec, quantity, drawingNumber, notes.';

const _piid = (ctx.complyResult && ctx.complyResult.intake_id) ? ctx.complyResult.intake_id : $('Extract Intake Data').first().json.intakeId;

const stepsRun = preprocessorSteps.length;
const stepsSkipped = Object.values(preprocessedData).filter(v => v && v.skipped).length;
const stepsOk = stepsRun - stepsSkipped;

try {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _piid,
      stepKey: 'sanitize_pii',
      status: 'success',
      log: `Entities tokenized \u00b7 job: ${(ctx.sanitizeJobId||'').slice(0,8)} \u00b7 file: ${ctx.complyResult?.filename||'?'}`,
    },
  });
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _piid,
      stepKey: 'type_detection',
      status: 'success',
      log: `Detected ${ctx.typeCode || 'UT'} (${ctx.typeLabel || 'Ultrasonic Testing'}) \u00b7 matched: "${ctx.matchedKeyword||'default UT'}"`,
      detail: { typeCode: ctx.typeCode, typeLabel: ctx.typeLabel, matchedKeyword: ctx.matchedKeyword },
    },
  });
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _piid,
      stepKey: 'preprocessor',
      status: 'success',
      log: `${stepsOk} steps executed \u00b7 ${stepsSkipped} skipped \u00b7 type: ${ctx.typeCode}`,
      detail: { stepsTotal: stepsRun, stepsOk, stepsSkipped, typeCode: ctx.typeCode },
    },
  });
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: { intakeId: _piid, stepKey: 'llm_analysis', status: 'processing', log: `Starting LLM analysis \u00b7 ${llmSteps.length} step(s) configured` },
  });
} catch (_) {}

return [{
  json: {
    preprocessedData,
    allLlmSteps: llmSteps,
    llmInstruction: llmStep?.instruction || defaultInstruction,
    sanitizedText: ctx.sanitizedText,
    sanitizeJobId: ctx.sanitizeJobId,
    complyResult: ctx.complyResult,
    typeCode: ctx.typeCode,
    typeLabel: ctx.typeLabel,
    matchedKeyword: ctx.matchedKeyword,
    stepProvider: llmStep?.provider || null,
    stepModel: llmStep?.model || null,
    intakeId: _piid,
    defaultInstruction,
  }
}];

// Loop through ALL configured LLM steps for this inspection type.
// Each step can override provider/model. Results are merged into one combinedOutput.
const preprocessor = $input.first().json;
const {
  allLlmSteps,
  sanitizedText,
  sanitizeJobId,
  complyResult,
  typeCode,
  intakeId: _piid,
  defaultInstruction,
} = preprocessor;

const GATEWAY_URL = 'http://gateway:8012/analyze';
const API_URL     = 'http://api:3100/integrations/pipeline/step-update';

// Drawing image for RT vision pipeline
const drawingB64       = $('Branch B: PDF to Image').first().json.content_b64 || null;
const drawingMediaType = $('Branch B: PDF to Image').first().json.media_type || 'image/png';
const isImageMedia     = drawingMediaType && drawingMediaType.startsWith('image/');

// Fall back to a single default step if none are configured
const llmSteps = Array.isArray(allLlmSteps) && allLlmSteps.length > 0
  ? allLlmSteps
  : [{ instruction: defaultInstruction, provider: null, model: null, name: 'default', id: 'default' }];

let combinedOutput = {};
let lastResponse   = null;
let totalTokens    = 0;
const stepResults  = [];

for (let i = 0; i < llmSteps.length; i++) {
  const step = llmSteps[i];
  const isLast = i === llmSteps.length - 1;

  // Mark step as processing
  try {
    await this.helpers.httpRequest({
      method: 'POST', url: API_URL,
      headers: { 'Content-Type': 'application/json' },
      body: {
        intakeId: _piid,
        stepKey: 'llm_analysis',
        status: 'processing',
        log: `Step ${i + 1}/${llmSteps.length}: ${step.name || 'LLM'} \u00b7 provider: ${step.provider || 'auto'}`,
      },
    });
  } catch (_) {}

  const gatewayBody = {
    intake_id: _piid,
    sanitize_job_id: sanitizeJobId,
    classification: complyResult.classification,
    llm_routing: complyResult.llm_routing,
    prompt: sanitizedText || '',
    system_prompt: step.instruction || defaultInstruction,
  };
  if (step.provider) gatewayBody.provider = step.provider;
  if (step.model)    gatewayBody.model    = step.model;
  // Pass engineering drawing as vision input for RT jobs
  // For RT jobs, supplement the attachment text with sanitized email context
  // (PDF binary content is unreadable; email body has the actual weld specs)
  if (typeCode === 'RT') {
    const sanitizedEmailText = $('Branch A: Sanitize Email').first()?.json?.sanitized_text || '';
    if (sanitizedEmailText) {
      gatewayBody.prompt = `EMAIL (contains weld specs and dimensions):
${sanitizedEmailText}

ATTACHMENT TEXT (may be binary/unreadable):
${sanitizedText || ''}`;
    }
  }
  if (typeCode === 'RT' && drawingB64 && isImageMedia) {
    gatewayBody.images = [{ media_type: drawingMediaType, data_b64: drawingB64 }];
  }

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: GATEWAY_URL,
      headers: { 'Content-Type': 'application/json' },
      body: gatewayBody,
      timeout: 300000,
    });

    lastResponse = res;
    totalTokens += res.prompt_tokens || 0;

    // Merge structured JSON output (later steps can refine/add fields)
    let parsed = {};
    try {
      parsed = typeof res.response_json === 'string'
        ? JSON.parse(res.response_json)
        : (res.response_json || {});
    } catch (_) {}
    Object.assign(combinedOutput, parsed);

    stepResults.push({
      stepName: step.name,
      provider: res.provider_used,
      model: res.model_used,
      tokens: res.prompt_tokens,
      success: true,
    });
  } catch (err) {
    stepResults.push({
      stepName: step.name,
      success: false,
      error: err.message,
    });
    // Non-fatal: continue to next step
  }
}

// Final status update — success if at least one step succeeded
const anySuccess = stepResults.some(r => r.success);
const statusStr  = anySuccess ? 'success' : 'failed';
const stepSummary = stepResults
  .map(r => r.success ? `${r.stepName}:ok` : `${r.stepName}:err`)
  .join(', ');

try {
  await this.helpers.httpRequest({
    method: 'POST', url: API_URL,
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _piid,
      stepKey: 'llm_analysis',
      status: statusStr,
      log: `${llmSteps.length} LLM step(s) \u00b7 ${totalTokens} tokens \u00b7 ${stepSummary}`,
      detail: {
        stepsRun: llmSteps.length,
        stepResults,
        provider: lastResponse?.provider_used,
        model: lastResponse?.model_used,
        totalTokens,
        drawing_b64: (typeCode === 'RT' && isImageMedia) ? drawingB64 : null,
        drawing_media_type: (typeCode === 'RT' && isImageMedia) ? drawingMediaType : null,
        pii_regions_redacted: $('Branch B: PDF to Image').first().json.pii_regions_redacted ?? null,
      },
      serviceName: 'gateway',
      endpoint: GATEWAY_URL,
      httpStatus: 200,
      requestPayload: { intake_id: _piid, sanitize_job_id: sanitizeJobId, classification: complyResult.classification, llm_routing: complyResult.llm_routing, prompt: (sanitizedText || '').slice(0, 3000), system_prompt: (llmSteps[0]?.instruction || defaultInstruction || '').slice(0, 500) },
      responsePayload: { provider: lastResponse?.provider_used, model: lastResponse?.model_used, tokens: totalTokens, response_json: JSON.stringify(combinedOutput).slice(0, 5000), step_results: stepResults },
    },
  });
} catch (_) {}

// RT vision pipeline: submit quote directly to /rt/quote if L3 tech analysis returned RT structure
let rtQuoteId = null;
if (combinedOutput.quote_type === 'RT' && Array.isArray(combinedOutput.views) && combinedOutput.views.length > 0) {
  try {
    const rtResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://api:3100/rt/quote',
      headers: { 'Content-Type': 'application/json' },
      body: combinedOutput,
      timeout: 30000,
    });
    rtQuoteId = rtResp.quoteId || null;
    await this.helpers.httpRequest({
      method: 'POST', url: API_URL,
      headers: { 'Content-Type': 'application/json' },
      body: {
        intakeId: _piid,
        stepKey: 'quote_created',
        status: 'success',
        log: `RT quote created \u00b7 ${rtQuoteId} \u00b7 ${(combinedOutput.views||[]).length} view(s)`,
        detail: { rtQuoteId, quoteType: 'RT', viewCount: (combinedOutput.views||[]).length },
      },
    });
  } catch (err) {
    // Non-fatal — RT quote submission failed; log only
    try {
      await this.helpers.httpRequest({
        method: 'POST', url: API_URL,
        headers: { 'Content-Type': 'application/json' },
        body: { intakeId: _piid, stepKey: 'quote_created', status: 'failed', log: `RT quote submission failed: ${err.message}` },
      });
    } catch (_) {}
  }
}

return [{
  json: {
    response_json: JSON.stringify(combinedOutput),
    provider_used: lastResponse?.provider_used,
    model_used: lastResponse?.model_used,
    prompt_tokens: totalTokens,
    rtQuoteId,
  }
}];

const classify = $('Branch B: Comply Classify').first().json;
const gateway = $input.first().json;
const preprocessor = $('B: Execute Preprocessor Steps').first().json;

const _ciid = classify.intake_id || $('Extract Intake Data').first().json.intakeId;
try {
  const rj = (typeof gateway.response_json === 'string'
    ? JSON.parse(gateway.response_json)
    : gateway.response_json) || {};
  const extracted = [
    rj.partNumber && `part: ${rj.partNumber}`,
    rj.material && `mat: ${rj.material}`,
    rj.quantity && `qty: ${rj.quantity}`,
    rj.ndeSpec && `spec: ${rj.ndeSpec}`,
  ].filter(Boolean).join(' \u00b7 ') || 'no structured params extracted';

  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId: _ciid,
      stepKey: 'llm_analysis',
      status: 'success',
      log: `${gateway.provider_used||'?'}/${gateway.model_used||'?'} \u00b7 ${gateway.prompt_tokens ?? '?'} tokens \u00b7 ${extracted}`,
      detail: {
        provider: gateway.provider_used,
        model: gateway.model_used,
        tokens: gateway.prompt_tokens,
        partNumber: rj.partNumber,
        material: rj.material,
        quantity: rj.quantity,
        ndeSpec: rj.ndeSpec,
      },
      serviceName: 'gateway',
      endpoint: 'http://gateway:8012/analyze',
      httpStatus: 200,
      requestPayload: { intake_id: _ciid, classification: classify.classification, llm_routing: classify.llm_routing },
      responsePayload: { provider: gateway.provider_used, model: gateway.model_used, tokens: gateway.prompt_tokens },
    },
  });
} catch (_) {}
return [{
  json: {
    doc_id: classify.doc_id,
    filename: classify.filename,
    classification: classify.classification,
    llm_routing: classify.llm_routing,
    risk_score: classify.risk_score,
    drawing_number: classify.drawing_number,
    provider_used: gateway.provider_used,
    model_used: gateway.model_used,
    typeCode: preprocessor.typeCode,
    typeLabel: preprocessor.typeLabel,
    matchedKeyword: preprocessor.matchedKeyword,
    preprocessed_data: preprocessor.preprocessedData,
    llm_output: gateway.response_json,
    rtQuoteId: gateway.rtQuoteId || null,
  }
}];

const items = $input.all();
const intakeId = $('Extract Intake Data').first().json.intakeId;

// Find email analysis result
const emailResult = items.find(i => i.json.source === 'email' || i.json.email_analysis);

// Find attachment results
const attachResults = items.filter(i => i.json.doc_id);

// Determine strictest routing
const routings = ['CLOUD_OK', 'LOCAL_ONLY', 'HOLD'];
const allRoutings = attachResults.map(r => r.json.llm_routing || 'CLOUD_OK');
let strictest = 'CLOUD_OK';
for (const r of allRoutings) {
  if (routings.indexOf(r) > routings.indexOf(strictest)) {
    strictest = r;
  }
}

// Extract quote params from email LLM output
const emailParsed = emailResult?.json?.response_json?.parsed || emailResult?.json?.llm_output || {};

// Build classifications array (includes typeCode/typeLabel and preprocessed_data)
const classifications = attachResults.map(r => ({
  filename: r.json.filename,
  classification: r.json.classification,
  llm_routing: r.json.llm_routing,
  risk_score: r.json.risk_score,
  drawing_number: r.json.drawing_number,
  provider_used: r.json.provider_used,
  typeCode: r.json.typeCode,
  typeLabel: r.json.typeLabel,
  matchedKeyword: r.json.matchedKeyword,
  preprocessed_data: r.json.preprocessed_data,
  skipped_reason: r.json.skipped_reason || null,
}));

// RT quote ID from attachment results (vision pipeline)
const rtQuoteId = attachResults.find(r => r.json.rtQuoteId)?.json.rtQuoteId || null;

// Rich assemble log
const emailParsedForLog = emailResult?.json?.response_json || {};
const customer = emailParsedForLog.customerName || emailParsed.customerName || '?';
const itype = emailParsedForLog.inspectionType || emailParsed.inspectionType || '?';

try {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId,
      stepKey: 'assemble',
      status: 'success',
      log: `${strictest} \u00b7 ${attachResults.length} attachment(s) \u00b7 customer: ${customer} \u00b7 type: ${itype}`,
      detail: {
        strictestRouting: strictest,
        attachmentCount: attachResults.length,
        customerName: customer,
        inspectionType: itype,
      },
      requestPayload: {
        strictest_routing: strictest,
        attachment_count: attachResults.length,
        customer_name: customer,
        inspection_type: itype,
        classifications: classifications.map(c => ({
          filename: c.filename,
          classification: c.classification,
          routing: c.llm_routing,
          type_code: c.typeCode,
          drawing_number: c.drawing_number,
        })),
      },
    },
  });
} catch (_) {}
return [{
  json: {
    intakeId,
    strictestRouting: strictest,
    classifications,
    rtQuoteId,
    quoteParams: {
      customerName: emailParsed.customerName || '?',
      inspectionType: emailParsed.inspectionType || null,
      notes: emailParsed.notes || '',
      items: emailParsed.estimatedItems || []
    }
  }
}];

// Fetch 00-PRE inspection type + its steps from DB via API.
// Builds preProcConfig map keyed by config.pipeline_key.
// Non-fatal: on any error, passes empty map — pipeline uses hardcoded fallbacks.

const ctx = $input.first().json;
const API = 'http://api:3100';

let preProcConfig = {};

try {
  const types = await this.helpers.httpRequest({
    method: 'GET', url: `${API}/inspection-types`,
  });
  const preType = (Array.isArray(types) ? types : []).find(t => t.code === '00-PRE');

  if (preType) {
    const steps = await this.helpers.httpRequest({
      method: 'GET', url: `${API}/inspection-types/${preType.id}/steps`,
    });
    for (const step of (Array.isArray(steps) ? steps : [])) {
      const key = step.config?.pipeline_key;
      if (key) preProcConfig[key] = step;
    }
  }
} catch (err) {
  // Non-fatal: pipeline continues with hardcoded defaults
  preProcConfig._error = err.message;
}

return [{ json: { ...ctx, preProcConfig } }];

const ctx = $input.first().json;

// Pass through non-PDF files unchanged
if (!ctx.media_type || ctx.media_type !== 'application/pdf') {
  return [{ json: ctx }];
}

let result;
try {
  result = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://comply:8010/pdf-to-image',
    headers: { 'Content-Type': 'application/json' },
    body: { content_b64: ctx.content_b64, filename: ctx.filename },
    timeout: 60000,
  });
} catch (err) {
  // Non-fatal: log and pass through original (comply will still OCR the PDF text)
  console.warn('PDF-to-image failed:', err.message);
  return [{ json: ctx }];
}

return [{ json: {
  intakeId: ctx.intakeId,
  filename: ctx.filename,
  content_b64: result.image_b64,
  media_type: result.media_type,
  pdf_page_count: result.page_count,
  pii_regions_redacted: result.pii_regions_redacted || 0,
  original_media_type: 'application/pdf',
} }];

const ctx = $input.first().json;
const attachments = ctx.attachments || [];
if (attachments.length === 0) return [];

// Skip email decoration attachments (logos, banners, etc.)
const real = attachments.filter(a => !a.filtered);
if (real.length === 0) return [];

return real.map(att => ({
  json: {
    intakeId: ctx.intakeId,
    filename: att.filename,
    // Encode the downloadUrl to handle spaces/special chars in folder/file names
    downloadUrl: att.downloadUrl
      ? att.downloadUrl.split('/').map((seg, i) => i > 2 ? encodeURIComponent(decodeURIComponent(seg)) : seg).join('/')
      : att.downloadUrl,
    size: att.size,
    filtered: att.filtered,
    filterReason: att.filterReason,
    preProcConfig: ctx.preProcConfig,
    email: ctx.email,
  }
}));

const intakeId = $('Extract Intake Data').first().json.intakeId;
const emailFrom = $('Extract Intake Data').first().json.email?.from || '';
const emailAnalysis = $input.first().json;

const llmJson = (typeof emailAnalysis.response_json === 'string'
  ? JSON.parse(emailAnalysis.response_json)
  : emailAnalysis.response_json) || {};
const partNumber = llmJson.partNumber || 'N/A';

try {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
    headers: { 'Content-Type': 'application/json' },
    body: {
      intakeId, stepKey: 'retrieve_history', status: 'processing',
      log: `Looking up history \u00b7 part: ${partNumber} \u00b7 sender: ${emailFrom}`,
      serviceName: 'api', endpoint: 'http://api:3100/integrations/pipeline/history-lookup',
      requestPayload: { partNumber, emailDomain: emailFrom.split('@')[1] || '' },
    },
  });
} catch (_) {}

const t0 = Date.now();
let historyResult = null;
try {
  historyResult = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://api:3100/integrations/pipeline/history-lookup',
    headers: { 'Content-Type': 'application/json' },
    body: { intakeId, emailFrom, partNumber },
  });
} catch (err) {
  historyResult = { error: err.message };
}
const latencyMs = Date.now() - t0;
const ok = historyResult && !historyResult.error;

try {
  if (ok) {
    const ph = historyResult.partHistory || {};
    const ac = historyResult.accountContext || {};
    const pi = historyResult.priorIntakes || {};
    const logLines = [
      historyResult.summary || 'History lookup complete',
      `Part: ${partNumber} \u00b7 found: ${ph.found ? 'YES' : 'NO'} \u00b7 jobs: ${ph.jobs?.length || 0} \u00b7 quotes: ${ph.quotes?.length || 0}`,
      ph.bom ? `BOM: avg $${Number(ph.bom.avg_invoice||0).toFixed(2)} \u00b7 max $${Number(ph.bom.max_invoice||0).toFixed(2)} \u00b7 ${ph.bom.job_count} historical jobs` : 'BOM: no aggregated data',
      ph.bom?.specifications?.length ? `Specs: ${ph.bom.specifications.join(', ')}` : 'Specs: none on record',
      ph.bom?.procedures?.length ? `Procedures: ${ph.bom.procedures.join(', ')}` : 'Procedures: none on record',
      `Account match (${ac.matchedBy}): ${ac.accounts?.map(a => a.name).join(', ') || 'none'}`,
      `Prior intakes from this sender: ${pi.count || 0}`,
      historyResult.isNewClient ? '*** NEW CLIENT \u2014 no account or intake history found ***' : 'Returning client context loaded',
    ];
    await this.helpers.httpRequest({
      method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
      headers: { 'Content-Type': 'application/json' },
      body: {
        intakeId, stepKey: 'retrieve_history', status: 'success',
        log: logLines,
        detail: historyResult,
        serviceName: 'api', endpoint: 'http://api:3100/integrations/pipeline/history-lookup',
        httpStatus: 200, latencyMs,
        responsePayload: historyResult,
      },
    });
  } else {
    await this.helpers.httpRequest({
      method: 'POST', url: 'http://api:3100/integrations/pipeline/step-update',
      headers: { 'Content-Type': 'application/json' },
      body: {
        intakeId, stepKey: 'retrieve_history', status: 'skipped',
        log: `History lookup failed \u00b7 ${historyResult?.error || 'API unavailable'} \u00b7 continuing without history`,
        serviceName: 'api', endpoint: 'http://api:3100/integrations/pipeline/history-lookup',
        httpStatus: 500, latencyMs,
        responsePayload: { error: historyResult?.error || 'API unavailable' },
      },
    });
  }
} catch (_) {}

return [{ json: { ...emailAnalysis, historyResult: ok ? historyResult : null } }];

